<?php
namespace App\Http\Controllers;
use App\Models\Kategoris; use Illuminate\Http\Request;
class KategorisController extends Controller { public function index(){return view('kategoris.index',['kategoris'=>Kategoris::withCount('alats')->latest()->paginate(15)]);} public function create(){return view('kategoris.form');} public function store(Request $r){Kategoris::create($r->validate(['nama_kategori'=>'required|string|max:255','deskripsi'=>'nullable|string']));return redirect()->route('kategoris.index')->with('sukses','Kategori berhasil ditambahkan.');} public function show(Kategoris $kategori){return redirect()->route('kategoris.edit',$kategori);} public function edit(Kategoris $kategori){return view('kategoris.form',compact('kategori'));} public function update(Request $r,Kategoris $kategori){$kategori->update($r->validate(['nama_kategori'=>'required|string|max:255','deskripsi'=>'nullable|string']));return redirect()->route('kategoris.index')->with('sukses','Kategori diperbarui.');} public function destroy(Kategoris $kategori){if($kategori->alats()->exists())return back()->with('error','Kategori masih dipakai oleh alat.');$kategori->delete();return redirect()->route('kategoris.index')->with('sukses','Kategori dihapus.');} }
